SELECT MIN(GSserved) AS lowest_grade_served
FROM schools
WHERE NCESDist = '0632640';

SELECT COUNT(*) AS ruling_count
FROM rulings
WHERE uuid IN (
    SELECT uuid FROM cards WHERE name = "Mishra's Factory"
)
AND date = (
    SELECT MAX(date) FROM rulings WHERE uuid IN (
        SELECT uuid FROM cards WHERE name = "Mishra's Factory"
    )
)

SELECT COUNT(*) AS total_rulings
FROM rulings
WHERE text LIKE '%Fireball%';

SELECT COUNT(DISTINCT language) AS num_languages
FROM foreign_data
WHERE name = 'Swamp';

SELECT COUNT(*) AS character_count
FROM superhero
WHERE publisher_id = (
    SELECT publisher_id FROM superhero WHERE superhero_name = 'A-Bomb'
)
AND race_id IS NULL;

