SELECT ROUND(100.0 * COUNT(CASE WHEN strftime('%Y', Birthday) >= '1960' THEN 1 END) / COUNT(*), 1) AS percentage_1960_or_later
FROM Patient
WHERE Diagnosis = 'psoriatic arthritis';

SELECT DISTINCT p.ID as Patient_ID, p.SEX, p.Birthday
FROM Patient p
WHERE EXISTS (
  SELECT 1 FROM Laboratory l1 WHERE l1.ID = p.ID AND l1.LDH >= 500
) AND EXISTS (
  SELECT 1 FROM Laboratory l2 WHERE l2.ID = p.ID AND (
    (l2."U-PRO" GLOB '*[0-9]*' AND CAST(l2."U-PRO" AS FLOAT) >= 100) OR l2."U-PRO" = '100'
  )
)
ORDER BY p.ID;

