WITH carcinogenic_molecules AS (
    SELECT id FROM molecule WHERE carcinogenic = 1
),
fluorine_atoms AS (
    SELECT DISTINCT molecule_id FROM atom WHERE element = 'F'
),
carcinogenic_with_fluorine AS (
    SELECT id FROM carcinogenic_molecules
    WHERE id IN (SELECT molecule_id FROM fluorine_atoms)
),
carcinogenic_without_fluorine AS (
    SELECT id FROM carcinogenic_molecules
    WHERE id NOT IN (SELECT molecule_id FROM fluorine_atoms)
)
SELECT
    ROUND(
        (SELECT COUNT(*) FROM carcinogenic_without_fluorine) * 100.0 /
        (SELECT COUNT(*) FROM carcinogenic_molecules), 2
    ) AS percent_carcinogenic_without_fluorine
;
